package day5;

public class Program5_Break_While {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Hello");
		int num=1;
		while(num<=10)
		{
			System.out.print(num+" ");
			if(num==5)
				break;
			num++;
			
		}
        System.out.println("\nBye");	
	}

}
